  "check_code": "import sqlite3
from pathlib import Path


SYSTEM_NAME = "epic_resolute_pb_exceptions"
TARGET_EXCEPTION = "EXC-CF-202509-011"
EVIDENCE_NOTE = "CareFirst_Credential_Rejection_Remediation_Report_2025-09-19.docx"


def _paths(workspace):
    system_dir = Path(workspace).resolve().parent / "system" / SYSTEM_NAME
    return system_dir / "state.db"


def _connect(path):
    connection = sqlite3.connect(path)
    connection.row_factory = sqlite3.Row
    return connection


def check_target_root_cause_state(workspace):
    current_path = _paths(workspace)
    try:
        with _connect(current_path) as connection:
            rows = connection.execute(
                """
                SELECT exception_id, root_cause_code, npi_format_valid,
                       payer_credential_aligned, disposition_code
                FROM credential_exception_cases
                WHERE exception_id = ?
                """,
                (TARGET_EXCEPTION,),
            ).fetchall()
    except Exception as exc:
        return {"score": 0, "detail": f"Unable to inspect the target exception: {exc}"}

    expected = {
        "exception_id": TARGET_EXCEPTION,
        "root_cause_code": "PAYER_MAPPING",
        "npi_format_valid": 1,
        "payer_credential_aligned": 0,
        "disposition_code": "RELEASE_APPROVED",
    }
    actual = dict(rows[0]) if len(rows) == 1 else None
    passed = len(rows) == 1 and actual == expected
    return {
        "score": int(passed),
        "detail": f"Expected one classified target row {expected}; found {actual} with row count {len(rows)}.",
    }


def check_single_auditable_classification(workspace):
    current_path = _paths(workspace)
    try:
        with _connect(current_path) as connection:
            rows = connection.execute(
                """
                SELECT exception_id, action_type, actor_id, approval_result,
                       note_category, source_action_key
                FROM exception_actions
                WHERE exception_id = ? AND action_type = 'ROOT_CAUSE_CLASSIFIED'
                """,
                (TARGET_EXCEPTION,),
            ).fetchall()
    except Exception as exc:
        return {"score": 0, "detail": f"Unable to inspect classification actions: {exc}"}

    expected = {
        "exception_id": TARGET_EXCEPTION,
        "action_type": "ROOT_CAUSE_CLASSIFIED",
        "actor_id": "USR-RCM-104",
        "approval_result": "CONFIRMED",
        "note_category": "ROOT_CAUSE",
        "source_action_key": EVIDENCE_NOTE,
    }
    actual = dict(rows[0]) if len(rows) == 1 else None
    passed = len(rows) == 1 and actual == expected
    return {
        "score": int(passed),
        "detail": f"Expected exactly one matching classification action {expected}; found {len(rows)} action(s): {[dict(row) for row in rows]}.",
    }


def check_case_table_integrity(workspace):
    current_path = _paths(workspace)
    try:
        with _connect(current_path) as current:
            target_count = current.execute(
                "SELECT COUNT(*) FROM credential_exception_cases WHERE exception_id = ?",
                (TARGET_EXCEPTION,),
            ).fetchone()[0]
            other_summary = dict(
                current.execute(
                    """
                    SELECT COUNT(*) AS case_count,
                           COUNT(DISTINCT exception_id) AS distinct_ids,
                           SUM(claim_amount_cents) AS total_amount_cents,
                           SUM(npi_format_valid) AS valid_npi_count,
                           SUM(payer_credential_aligned) AS aligned_count,
                           SUM(CASE WHEN disposition_code = 'RELEASE_APPROVED' THEN 1 ELSE 0 END) AS release_count,
                           SUM(CASE WHEN disposition_code = 'HOLD' THEN 1 ELSE 0 END) AS hold_count
                    FROM credential_exception_cases
                    WHERE exception_id <> ?
                    """,
                    (TARGET_EXCEPTION,),
                ).fetchone()
            )
    except Exception as exc:
        return {"score": 0, "detail": f"Unable to verify case-table integrity: {exc}"}

    expected_summary = {
        "case_count": 86,
        "distinct_ids": 86,
        "total_amount_cents": 13941139,
        "valid_npi_count": 84,
        "aligned_count": 2,
        "release_count": 71,
        "hold_count": 3,
    }
    passed = target_count == 1 and other_summary == expected_summary
    return {
        "score": int(passed),
        "detail": f"Target case count is {target_count}; non-target control summary is {other_summary}.",
    }


def check_action_history_integrity(workspace):
    current_path = _paths(workspace)
    try:
        with _connect(current_path) as current:
            rows = [
                dict(row)
                for row in current.execute(
                    """
                    SELECT action_id, exception_id, action_type, actor_id, action_at,
                           approval_result, note_category, source_action_key
                    FROM exception_actions
                    WHERE exception_id = ?
                    ORDER BY action_at, action_id
                    """,
                    (TARGET_EXCEPTION,),
                )
            ]
    except Exception as exc:
        return {"score": 0, "detail": f"Unable to verify action history: {exc}"}

    imported_notes = [row for row in rows if row["note_category"] == "IMPORTED_ANALYST_NOTE"]
    classifications = [row for row in rows if row["action_type"] == "ROOT_CAUSE_CLASSIFIED"]
    imported_history_preserved = {
        (row["action_id"], row["actor_id"], row["source_action_key"])
        for row in imported_notes
    } == {
        ("ACT-CF-011-004", "USR-RCM-104", "SRC-CF-011-NOTE-1"),
        ("ACT-CF-011-005", "USR-RCM-104", "SRC-CF-011-NOTE-1"),
    }
    passed = len(rows) == 3 and imported_history_preserved and len(classifications) == 1
    return {
        "score": int(passed),
        "detail": f"Target timeline has {len(rows)} rows, {len(imported_notes)} preserved imported notes, and {len(classifications)} classification action(s).",
    }
